/**
 * PDF text extraction — best effort, no native PDF text layer library.
 *
 * This is the deliberately fragile piece (flagged in the build plan): there
 * is no solid pure-JS PDF text extractor that works in React Native without
 * Node's `fs`/`zlib`. Most real-world PDFs compress their content streams
 * with FlateDecode, which this lightweight scanner cannot inflate, so it only
 * recovers text from *uncompressed* PDFs (common for PDFs generated by simple
 * "print to PDF" tools, some government forms, and text-only exports).
 *
 * When it can't find a usable text layer, it returns null rather than
 * guessing — callers must surface that clearly to the user instead of
 * silently producing an empty/garbage summary. Swapping in a proper
 * PDF-to-text or PDF-render-to-image (then OCR) pipeline later only requires
 * changing this one function.
 */
import * as FileSystem from 'expo-file-system';

// Matches "(...)Tj" and "[(...) ... ]TJ" text-showing operators in an
// uncompressed PDF content stream, capturing the literal string content.
const TEXT_SHOW_RE = /\(((?:[^()\\]|\\.)*)\)\s*Tj|\[((?:\([^()]*\)|[^\]])*)\]\s*TJ/g;
const PAREN_STRING_RE = /\(([^()]*)\)/g;

function unescapePdfString(s: string): string {
  return s
    .replace(/\\\(/g, '(')
    .replace(/\\\)/g, ')')
    .replace(/\\\\/g, '\\')
    .replace(/\\n/g, '\n')
    .replace(/\\r/g, '\r')
    .replace(/\\t/g, '\t');
}

function scanForText(raw: string): string {
  const lines: string[] = [];
  let match: RegExpExecArray | null;
  TEXT_SHOW_RE.lastIndex = 0;
  while ((match = TEXT_SHOW_RE.exec(raw))) {
    if (match[1] !== undefined) {
      lines.push(unescapePdfString(match[1]));
    } else if (match[2] !== undefined) {
      let inner: RegExpExecArray | null;
      PAREN_STRING_RE.lastIndex = 0;
      let line = '';
      while ((inner = PAREN_STRING_RE.exec(match[2]))) {
        line += unescapePdfString(inner[1]);
      }
      if (line) lines.push(line);
    }
  }
  return lines.join(' ').replace(/\s+/g, ' ').trim();
}

export async function extractPdfText(uri: string): Promise<string | null> {
  try {
    // Read as 'binary'-ish latin1 text so byte-for-byte content-stream bytes
    // round-trip through regex matching without UTF-8 mangling.
    const raw = await FileSystem.readAsStringAsync(uri, { encoding: FileSystem.EncodingType.UTF8 }).catch(
      () => null
    );
    if (!raw) return null;
    const text = scanForText(raw);
    return text.length > 20 ? text : null;
  } catch (error) {
    console.error('[Docs] PDF extraction failed:', error);
    return null;
  }
}
